pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // fuzz: an address owner and a tokenId and an amount to mint
    function testFuzz_property(address owner, uint256 tokenId, uint256 amount) public {
        // keep tokenId and amount in reasonable ranges but wide
        tokenId = tokenId % 20; // allow up to 20 different token types
        amount = amount % 1000; // small amounts to avoid overflow

        // ensure caller is admin to create items
        // set this contract as admin in constructor already

        // create a game item if not exists up to tokenId
        // create items until we have tokenId index
        uint256 existing = c.uniqueTokensOutstanding();
        for (uint256 i = existing; i <= tokenId; ++i) {
            // createGameItem(name_, tokenURI, finiteSupply, transferable, itemsRemaining, itemPrice, dailyAllowance)
            c.createGameItem("itm", "uri", false, true, 10000, 0, 1);
        }

        // mint some tokens to owner using internal mint function by calling from owner via prank
        // The ERC1155 _mint is internal; but C.mint is public and buys with NRN — cannot use.
        // Instead, leverage createGameItem then use c._mint is internal so we simulate by calling burn/mint flows unavailable.
        // Alternative: call c.safeTransferFrom not possible. However, ERC1155 has public mint via C._mint only internal.
        // Workaround: use the contract itself (this) which is admin and has created token; call internal-like path by invoking C (since setUp deployer is admin and we are inside test contract) — but cannot call internal.
        // Simpler approach: use the public balance-related APIs: after creation, balances are zero; we can call balanceOf and assert it's equal to stored (which is zero).
        // To ensure distinction, we try to simulate a nonzero stored balance by having the contract mint to itself via buying flow is impossible without NRN instance.
        // However the mutant differs whenever stored > 0; but reference always returns stored. We must allow fuzzer to find inputs where stored>0—create by invoking _mint through a helper contract that is the owner deployer and calls C.createGameItem and then calls C._mint? Can't call internal.
        // Alternative: use C.mint (public) which requires paying NRN; but Neuron instance not instantiated, so c._neuronInstance is zero address and calling balanceOf on zero address would revert. So instead we can directly interact with storage by transferring tokens via ERC1155 internal mechanisms: but not possible externally.
        // Simpler robust universal property: for any account & tokenId, balanceOf(account, tokenId) when account == address(0) reverts in both versions. But mutant unchanged revert; must assert equality of behavior: call balanceOf for address(0) should revert. That holds in reference and mutant. But mutant also reverts same — doesn't distinguish.
        // Need test that passes on reference for all inputs and fails on mutant for some inputs. The only observable difference is doubling nonzero stored balances. We can create a nonzero balance by calling C._mint via a helper contract that inherits C and exposes a public wrapper to call the internal _mint. Deploy such helper, then mint to a fuzzed owner address, then call balanceOf and check equality: balanceOf(owner,id) * 2 != stored for mutant. But rule must be universal: reference returns stored value; so assert that c.balanceOf(owner,id) * 2 != c.balanceOf(owner,id) ??? Need one assert reading c only.
        // Approach: deploy a small Helper that inherits C and exposes a function to mint tokens (calls internal _mint). Use that helper's instance as the tested contract? But spec requires using c = new C(address(this), address(this)) in setUp exactly. We cannot change that.
        // However we can deploy a separate helper that has a function to call c's internal? Can't.
        // Different approach: use safeTransferFrom to move tokens from msg.sender to someone else — but initial balances zero. But ERC1155._mint in C is internal so only contract itself can mint to address. But the constructor of C didn't mint any tokens. So we cannot get nonzero balances unless some public function mints. The C.mint function mints by deducting NRN; but Neuron instance uninstantiated so instantiateNeuronContract required. We can deploy a Neuron and set balances and approve and instantiate.
        // So: deploy a Neuron token, mint NRN to owner, set c.instantiateNeuronContract, then call c.mint to purchase tokens priced 0? itemPrice set earlier to 0 in createGameItem, so purchase price 0 and requires balance>=0 satisfied; c.mint will call _neuronInstance.approveSpender(msg.sender, price) with price 0 (safe), then transferFrom(msg.sender, treasuryAddress, 0) will succeed (ERC20 transferFrom requires allowance; for 0 should pass even without allowance), but transferFrom in ERC20 will call _spendAllowance which will revert if allowance insufficient unless currentAllowance == max or >= amount; for amount 0, _spendAllowance will check currentAllowance != max then require currentAllowance >= 0 which always true. But transferFrom requires that from has sufficient balance; transferring 0 from a zero balance is fine. So c.mint will proceed and then _mint ERC1155 will mint tokens to msg.sender.
        // Steps below implement this.

        // deploy a Neuron and instantiate in c
        Neuron nrn = new Neuron(address(this), address(this), address(this));
        c.instantiateNeuronContract(address(nrn));

        // ensure owner has sufficient NRN balance (price 0 so not necessary) but still fine
        // call c.mint as owner to buy 'amount' of tokenId
        vm.prank(owner);
        // calling mint will require msg.sender has NRN balance >= price (0) and will perform transferFrom of 0
        c.mint(tokenId, amount);

        // Now we can read balance
        bool ok;
        try c.balanceOf(owner, tokenId) returns (uint256 v) {
            ok = (v == v); // trivial true when returns; but we need a stronger universal assertion: reference returns stored value; mutant returns doubled — how to assert property that fails on mutant?
            // Instead assert that returned value equals c.getAllowanceRemaining? Not related.
        } catch {
            ok = false;
        }

        // The intended general rule: for any owner and tokenId, the reported balance equals the number of tokens actually held; since we just minted `amount`, the balance must equal amount.
        // So assert that c.balanceOf(owner, tokenId) == amount
        uint256 reported = c.balanceOf(owner, tokenId);
        assertTrue(reported == amount);
    }
}

// Minimal Neuron deployment used in test
contract Neuron is ERC20, AccessControl {
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");
    bytes32 public constant SPENDER_ROLE = keccak256("SPENDER_ROLE");
    bytes32 public constant STAKER_ROLE = keccak256("STAKER_ROLE");
    uint256 public constant INITIAL_TREASURY_MINT = 10**18 * 10**8 * 2;
    uint256 public constant INITIAL_CONTRIBUTOR_MINT = 10**18 * 10**8 * 5;
    uint256 public constant MAX_SUPPLY = 10**18 * 10**9;
    address public treasuryAddress;
    address _ownerAddress;
    mapping(address => bool) public isAdmin;
    constructor(address ownerAddress, address treasuryAddress_, address contributorAddress) ERC20("Neuron","NRN") {
        _ownerAddress = ownerAddress;
        treasuryAddress = treasuryAddress_;
        isAdmin[_ownerAddress] = true;
        _mint(treasuryAddress, INITIAL_TREASURY_MINT);
        _mint(contributorAddress, INITIAL_CONTRIBUTOR_MINT);
    }
    function transferOwnership(address newOwnerAddress) external { require(msg.sender == _ownerAddress); _ownerAddress = newOwnerAddress; }
    function addMinter(address newMinterAddress) external { require(msg.sender == _ownerAddress); _setupRole(MINTER_ROLE, newMinterAddress); }
    function addStaker(address newStakerAddress) external { require(msg.sender == _ownerAddress); _setupRole(STAKER_ROLE, newStakerAddress); }
    function addSpender(address newSpenderAddress) external { require(msg.sender == _ownerAddress); _setupRole(SPENDER_ROLE, newSpenderAddress); }
    function adjustAdminAccess(address adminAddress, bool access) external { require(msg.sender == _ownerAddress); isAdmin[adminAddress] = access; }
    function setupAirdrop(address[] calldata recipients, uint256[] calldata amounts) external { require(isAdmin[msg.sender]); require(recipients.length == amounts.length); uint256 recipientsLength = recipients.length; for (uint32 i = 0; i < recipientsLength; i++) { _approve(treasuryAddress, recipients[i], amounts[i]); } }
    function claim(uint256 amount) external { require(allowance(treasuryAddress, msg.sender) >= amount, "ERC20: claim amount exceeds allowance"); transferFrom(treasuryAddress, msg.sender, amount); }
    function mint(address to, uint256 amount) public virtual { require(totalSupply() + amount < MAX_SUPPLY, "Trying to mint more than the max supply"); require(hasRole(MINTER_ROLE, msg.sender), "ERC20: must have minter role to mint"); _mint(to, amount); }
    function burn(uint256 amount) public virtual { _burn(msg.sender, amount); }
    function approveSpender(address account, uint256 amount) public { require(hasRole(SPENDER_ROLE, msg.sender), "ERC20: must have spender role to approve spending"); _approve(account, msg.sender, amount); }
    function approveStaker(address owner, address spender, uint256 amount) public { require(hasRole(STAKER_ROLE, msg.sender), "ERC20: must have staker role to approve staking"); _approve(owner, spender, amount); }
    function burnFrom(address account, uint256 amount) public virtual { require(allowance(account, msg.sender) >= amount, "ERC20: burn amount exceeds allowance"); uint256 decreasedAllowance = allowance(account, msg.sender) - amount; _burn(account, amount); _approve(account, msg.sender, decreasedAllowance); }
}

