        uint256 itemPrice = 1;
        uint16 dailyAllowance = 10;

        c.createGameItem(name_, uri, finiteSupply, transferable, itemsRemaining, itemPrice, dailyAllowance);

        // instantiate a Neuron-like token isn't necessary; we only need to observe balanceOf.
        // Mint some of tokenId into buyer by calling c.mint via this contract as buyer simulation.
        // But c.mint requires msg.sender has enough NRN; instead we can directly call internal _mint via public mint function — c.mint is public and checks _neuronInstance balance and will revert if not set.
        // So we will mint by using createGameItem then use low-level trick: call c as owner to mint tokens to buyer via safeTransferFrom not available.
        // Simpler: use c._mint is internal. But we cannot call. Alternative: use createGameItem which doesn't mint. However contract has public storage mapping _balances and public balanceOf.
        // We can simulate stored balance by calling c.setAllowedBurningAddresses and burn? That needs existing balance.
        // Instead, exploit that ERC1155._mint is exposed via C.mint? The function C.mint(tokenId, quantity) is public but performs checks including _neuronInstance; it will revert if _neuronInstance not set or buyer lacks NRN.
        // Workaround: use the public function createGameItem then directly call c.safeTransferFrom from address(this) to address(this) will fail if no balance.
        // The permitted way: we can mint by calling c.createGameItem then call c.instantiateNeuronContract with a dummy Neuron that always approves and has high balance; but we cannot deploy Neuron here. Simpler: use the fact that C is ERC1155 and has internal _mint used by createGameItem? No.
        // Alternative approach: test property on zero balances: when stored balance == 0, reference and mutant both return 0 (no difference). To detect mutant we need stored>0. We'll create positive stored balance by calling createGameItem then using a helper contract that calls c.mint after installing a fake Neuron satisfying checks.

        // Deploy a minimal fake Neuron that replicates only the used interface: balanceOf, approveSpender, transferFrom
        FakeNeuron nrn = new FakeNeuron();
        // give buyer enough balance in fake neuron
        nrn.setBalance(buyer, 1000);
        // instantiate neuron in C
        c.instantiateNeuronContract(address(nrn));

        // Now have buyer buy by calling c.mint(tokenId, quantity) - function name is mint in C
        // But c.mint requires tokenId < _itemCount: we created exactly one item so tokenId must be 0
        vm.assume(tokenId == 0);

        // Ensure buyer has enough NRN for price: itemPrice * quantity
        // FakeNeuron's balance already set.

        // call as buyer
        vm.prank(buyer);
        // call mint to purchase (this will call into FakeNeuron.transferFrom which will succeed)
        c.mint(tokenId, quantity);

        // Now stored balance for buyer, tokenId should be equal to quantity
        uint256 returned = c.balanceOf(buyer, tokenId);

        // General rule: returned balance equals the stored balance; here stored balance should be quantity.
        // The mutant that doubles stored balance will return 2 * quantity for some inputs (quantity > 0).
        assertTrue(returned == quantity);
    }
}

// Minimal fake neuron that C expects: balanceOf, approveSpender, transferFrom
contract FakeNeuron {
    mapping(address => uint256) public balances;
    function setBalance(address who, uint256 amt) public { balances[who] = amt; }
    function balanceOf(address who) external view returns (uint256) { return balances[who]; }
    function approveSpender(address account, uint256 amount) external {
        // do nothing; C expects this to succeed
    }
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        if (balances[from] < amount) return false;
        balances[from] -= amount;
        balances[to] += amount;
        return true;
    }
}

